[
    { "id": "bq41", "question": "Gidrosferaning yerdagi iqlimni shakllantirishdagi asosiy roli nima?", "options": ["Faqat yomg'ir yog'diradi", "Quyosh issiqligini yutib va to'plab, haroratni mo'tadillashtiradi (Yerni haddan tashqari isib va sovib ketishdan asraydi)", "Shamollarni yo'q qiladi", "Faqat muzlaydi"], "answer_index": 1, "explanation": "To'g'ri! Dunyo okeani sayyoraning 'termoregulyatori' (harorat sozlagichi) hisoblanib, issiqlikni butun Yer shariga bir tekis tarqatadi." },
    { "id": "bq42", "question": "O'zbekistonda eng kam tarqalgan ekotizim qaysi?", "options": ["Cho'l", "Tog'", "To'qayzorlar", "Yaylovlar"], "answer_index": 2, "explanation": "To'g'ri! Daryo qirg'oqlaridagi to'qayzor o'rmonlar (To'qay ekotizimlari) inson ta'siri va suv kamayishi tufayli keskin qisqarib ketgan va eng kam tarqalgan." },
    { "id": "bq43", "question": "Qaysi qush turi O'zbekiston tog'larida uchrovchi eng yirik yirtqich qush (sanitar) hisoblanadi?", "options": ["Oqqush", "Qora tasqara", "Lochin", "Chug'urchiq"], "answer_index": 1, "explanation": "To'g'ri! Qora tasqara va boshqa yirik o'laksaxo'r qushlar tabiat sanitarlari bo'lib, ular Qizil kitobga kiritilgan." },
    { "id": "bq44", "question": "Fotosintez jarayonining teskarisi nima?", "options": ["Xemosintez", "Nafas olish", "Transpiratsiya", "Mutatsiya"], "answer_index": 1, "explanation": "To'g'ri! Nafas olish fotosintezning teskarisi bo'lib, unda kislorod yutiladi, organik modda parchalanib energiya va SO2 ajraladi." },
    { "id": "bq45", "question": "Insonlarning suvga munosabatidagi 'Suv izi' (Water footprint) nima?", "options": ["Suvdagi izlar", "Bir kishi yoki davlat tomonidan kundalik hayot va mahsulotlar yaratish uchun sarflanadigan chuchuk suvning umumiy hajmi", "Suvning to'lqinlanishi", "Suv sathi"], "answer_index": 1, "explanation": "To'g'ri! Masalan, 1 ta paxtali futbolka tayyorlash uchun 2500 litrdan ortiq (suv izi) suv sarflanadi." },
    { "id": "bq46", "question": "Tuproq tarkibida organik moddalar va gumus (chirindi) ko'p bo'lsa tuproq qanday nomlanadi?", "options": ["Sho'rxok", "Qoratuproq", "Qumli", "Toshloq"], "answer_index": 1, "explanation": "To'g'ri! Qoratuproqlar (chernozyom) eng unumdor va gumusga boy tuproqlar hisoblanadi." },
    { "id": "bq47", "question": "Suv tubidagi baliqlar nafas olishi uchun suvda qanday holat bo'lishi kerak?", "options": ["Suv issiq bo'lishi", "Suv sho'r bo'lishi", "Suvda erigan kislorod bo'lishi", "Suv tinch bo'lishi"], "answer_index": 2, "explanation": "To'g'ri! Suv hayvonlari suv molekulasidagi (H2O) kisloroddan emas, balki suvda erigan erkin kisloroddan nafas oladi." },
    { "id": "bq48", "question": "Biosferaning chegaralari qayerdan o'tadi?", "options": ["Faqat quruqlik", "Atmosferaning ozon qatlamigacha, gidrosferaning eng chuqur joyigacha va litosferaning bir necha kilometr chuqurligigacha", "Faqat suvda", "Olam bo'ylab"], "answer_index": 1, "explanation": "To'g'ri! Hayot ozon ekranidan tortib, okean tubi va yer ostigacha tarqalgan." },
    { "id": "bq49", "question": "Pestisidlar asosan nima uchun ishlatiladi?", "options": ["Havo tozalash uchun", "O'simlik zararkunandalari va kasalliklariga qarshi kurashish uchun", "Daraxt kesish uchun", "Qurilishda"], "answer_index": 1, "explanation": "To'g'ri! Lekin ulardan noto'g'ri foydalanish tuproq va suvlarni qattiq zaharlaydi." },
    { "id": "bq50", "question": "Bir gektar o'rmon bir yilda taxminan qancha karbonat angidridni yutib, kislorod chiqaradi?", "options": ["1 tonna", "10-20 tonna", "Hech qancha", "500 tonna"], "answer_index": 1, "explanation": "To'g'ri! O'rmonlar eng kuchli karbonat yutqichlardir." },
    { "id": "bq51", "question": "Atrof muhitga inson ta'siri kuchayishi qanday davr deb atalmoqda?", "options": ["Muzlik davri", "Antroposen", "Yura davri", "Kembriy"], "answer_index": 1, "explanation": "To'g'ri! Antroposen – inson faoliyati Yer sayyorasi geologiyasi va ekotizimiga hal qiluvchi ta'sir ko'rsatayotgan hozirgi davr." },
    { "id": "bq52", "question": "Chuchuk suv zahirasining qariyb uchdan bir qismi (suyuq holdagi) qayerda joylashgan?", "options": ["Ko'llarda", "Yer osti suvlarida (artezian, sizot)", "Daryolarda", "O'simliklarda"], "answer_index": 1, "explanation": "To'g'ri! Yer osti suvlari insoniyat uchun o'ta muhim bo'lgan toza ichimlik suvi zaxirasidir." },
    { "id": "bq53", "question": "Ekologik iz (Ecological footprint) nima?", "options": ["Hayvonning izi", "Insonlarning iste'moli va chiqindilarni yutish uchun zarur bo'lgan tabiat maydoni o'lchovi", "Karbonat angidrid izi", "O'rmondagi yo'l"], "answer_index": 1, "explanation": "To'g'ri! Ekologik iz inson tabiatning qancha qismini \"yeb bitirayotganini\" hisoblaydigan xalqaro o'lchovdir." },
    { "id": "bq54", "question": "Orol dengizini qutqarish xalqaro jamg'armasi qachon tashkil qilingan?", "options": ["1960 yil", "1993 yil", "2010 yil", "2020 yil"], "answer_index": 1, "explanation": "To'g'ri! Markaziy Osiyo davlatlari rahbarlari tomonidan 1993-yilda tashkil etilgan." },
    { "id": "bq55", "question": "Iqlim isishini qaysi o'rtacha ko'rsatkichdan oshirmaslik bo'yicha Parij bitimi imzolangan?", "options": ["5 gradus", "1.5 - 2 gradus Selsiy", "10 gradus", "0 gradus"], "answer_index": 1, "explanation": "To'g'ri! Yer sayyorasi o'rtacha harorati sanoat davridagidan 1.5 - 2 gradusdan oshib ketsa, qaytarib bo'lmas halokatli jarayonlar boshlanadi." },
    { "id": "bq56", "question": "Eng kam chiqindi chiqaruvchi energiya manbai qaysi?", "options": ["Ko'mir yoqish", "Neft yoqish", "Quyosh va shamol energiyasi (Muqobil energiya)", "O'tin yoqish"], "answer_index": 2, "explanation": "To'g'ri! Muqobil va qayta tiklanuvchi energiya manbalari atrof muhitga zaharli gazlar chiqarmaydi." },
    { "id": "bq57", "question": "Agar dunyo okeanidagi barcha muzliklar erisa, dengiz sathi taxminan qanchaga ko'tarilishi mumkin?", "options": ["1 metr", "5-10 metr", "60 metrdan ortiq", "Hech qancha"], "answer_index": 2, "explanation": "To'g'ri! Bu esa minglab qirg'oq shaharlarini suv ostida qoldiradi." },
    { "id": "bq58", "question": "Dunyodagi eng ko'p turdagi jonzotlarni o'z ichiga oluvchi hayvonot klassi qaysi?", "options": ["Sut emizuvchilar", "Qushlar", "Hasharotlar", "Baliqlar"], "answer_index": 2, "explanation": "To'g'ri! Yer yuzida aniqlangan jonzotlarning milliondan ortiq turini hasharotlar tashkil qiladi." },
    { "id": "bq59", "question": "Yomg'ir chuvalchanglari tuproqqa qanday ta'sir qiladi?", "options": ["Zarar yetkazadi", "Tuproqni yumshatib, havoga to'yintiradi va unumdorligini oshiradi", "Ekin ildizini yeydi", "Ta'siri yo'q"], "answer_index": 1, "explanation": "To'g'ri! Darvin ularni \"tabiat shudgorchilari\" deb atagan, ular tuproq sifatini yaxshilashda beqiyos o'ringa ega." },
    { "id": "bq60", "question": "Zaharlarni mutlaqo parchalay olmaydigan muhit qaysi?", "options": ["Tuproq", "Daryo suvi", "Plastiklar o'zi va radioaktiv moddalar", "Havo"], "answer_index": 2, "explanation": "To'g'ri! Ayniqsa radioaktiv qoldiqlar yuz minglab yillar davomida nurlanish tarqatib yotadi va hech narsaga parchalanmaydi." }
]
"@

$newPuzzlesStr = @"
[
    { "id": "bp41", "story": "Odam uyi yonidan oqib o'tadigan anhorni (ariqni) tozalayman deb, ichidagi barcha mayda o't-o'lan, toshlar va loyni betonlab tashladi.", "question": "Ariq suvi endi avvalgidek toza bo'ladimi?", "options": ["Ha, yanada toza bo'ladi", "Yo'q, chunki suvni tozalovchi tabiiy biofiltrlar (o'tlar, mikroorganizmlar) beton sababli yo'q qilindi", "Farqi yo'q"], "answer_index": 1, "explanation": "To'g'ri! Tabiiy o'zanlar (to'qaylar, suv tubi qatlami) suvdagi zaharli moddalarni yutib tozalab beruvchi \"filtr\" vazifasini bajaradi." },
    { "id": "bp42", "story": "Katta fermada chorva mollarining tez va ko'p go'sht berishi uchun ularga doimiy antibiotiklar berildi.", "question": "Ushbu go'shtni iste'mol qilishning insoniyatga ekologik zarari nimada?", "options": ["Go'sht shirin bo'ladi", "Insonda antibiotiklarga chidamli (davolab bo'lmaydigan) bakteriyalar (superbakteriyalar) shakllanishiga olib keladi", "Hech qanday"], "answer_index": 1, "explanation": "To'g'ri! Qishloq xo'jaligida antibiotiklarning ortiqcha qo'llanilishi ekotizimda mutatsiya qilingan daxshatli bakteriyalarni yaratadi." },
    { "id": "bp43", "story": "Fermer dala chetidagi katta daraxtni uya qurayotgan mayna va chumchuqlarga achchiqlanib kesib tashladi.", "question": "Ekinzor endi xavfsizmi?", "options": ["Ha, endi tinchlik", "Yo'q, qushlar bo'lmagani uchun dalani zararkunanda hasharotlar bosadi", "Hosil 2 barobar oshadi"], "answer_index": 1, "explanation": "To'g'ri! Hasharotxo'r qushlar qishloq xo'jaligini minglab tonna zararkunandalardan tozalab beradigan asosiy do'stlardir." },
    { "id": "bp44", "story": "Shahar meriyasi ko'chalardagi barglarni to'kib tashlagan katta yoshli chinorlarni \"xunuk\" deb, ularning o'rniga doim yashil archalarni ekdi.", "question": "Bu ekologik to'g'ri yechimmi?", "options": ["Ha, archalar qishda ham yashil", "Yo'q, keng bargli daraxtlar (chinor) yozda qalin soya beradi, changni yutadi, archa esa buni qilolmaydi", "Ikkisi bir xil"], "answer_index": 1, "explanation": "To'g'ri! Issiq iqlimli shaharlarda keng bargli daraxtlarning kesilishi shahar haroratini (issiqlik orollari) oshirib yuboradi." },
    { "id": "bp45", "story": "Dehqon yerni haydashda (shudgorlashda) tuproqning ustki va ostki qatlamlarini aralashtirib emas, faqat ustidan tekislab haydadi (no-till usuli).", "question": "Bu usul foydalimi?", "options": ["Zararli, o'simlik o'smaydi", "Juda foydali! Bu tuproq eroziyasini oldini oladi, namlikni saqlaydi va uglerodni yerda ushlab qoladi", "Faqat pul tejaydi"], "answer_index": 1, "explanation": "To'g'ri! Yerni kamroq haydash zamonaviy \"iqlimga do'stona\" qishloq xo'jaligi usulidir (Conservation agriculture)." },
    { "id": "bp46", "story": "Tadqiqotchilar Antarktida qorlari tarkibida mikroplastik (juda mayda plastik zarralari) topishdi.", "question": "Antarktidada odamlar yo'q bo'lsa, plastik u yerga qanday bordi?", "options": ["Sayyohlar tashlab ketgan", "Mikroplastik zarralari shamol, bulutlar va dengiz oqimlari orqali minglab kilometrlarga ko'chib boradi", "Bunday bo'lishi mumkin emas"], "answer_index": 1, "explanation": "To'g'ri! Atmosfera sirkulyatsiyasi orqali zaharli moddalar va mayda plastmassa butun Yer sayyorasiga, hatto kimsasiz joylarga ham tarqaladi." },
    { "id": "bp47", "story": "Zavod havoni tozalash uchun qimmat filtr o'rnatdi. Tutun yo'qoldi, ammo endi zavod chiqindi qattiq qoldiqlarni (filtrga tushgan zaharlarni) yerga ko'mib kelmoqda.", "question": "Muammo hal bo'ldimi?", "options": ["Ha, havo tozalandi", "Yo'q, ifloslanish havodan tuproqqa va yer osti suvlariga o'tdi (muammo joyini o'zgartirdi xolos)", "Ha, yer hammasini yutadi"], "answer_index": 1, "explanation": "To'g'ri! Ekologik muammoni shunchaki boshqa sferega o'tkazish bilan hal qilib bo'lmaydi, qoldiqlarni mutlaq zararsizlantirish kerak." },
    { "id": "bp48", "story": "Uy bekasi uyni tozalash uchun juda kuchli kimyoviy tozalash vositalaridan (xlor, kislotalar) ko'p foydalandi, so'ng ularni rakovinaga to'kib yubordi.", "question": "Bu zaharli suv qayerga boradi?", "options": ["O'z-o'zidan toza suvga aylanadi", "Kanalizatsiya orqali suv tozalash inshootlariga boradi, ammo u yerdagi foydali bakteriyalarni o'ldirib, oqova suvlarni tozalash tizimini buzadi", "Yer yutib yuboradi"], "answer_index": 1, "explanation": "To'g'ri! Maishiy kimyo vositalari kanalizatsiyadagi organik biologik filtrlarni o'ldiradi va daryolarga zahar bo'lib boradi." },
    { "id": "bp49", "story": "Davlat aholining go'shtga bo'lgan talabini qondirish uchun millionlab gektar tropik o'rmonlarni kesib, molxonalarga aylantirdi.", "question": "Bu globallashuv ekologiyasiga qanday xavf tug'diradi?", "options": ["Hech qanday", "O'rmonning kesilishi tufayli CO2 ko'payishi bilan birga, millionlab mollar ajratgan \"Metan\" (CH4) gazi iqlimni dahshatli isitadi", "Havo sovuq bo'lib ketadi"], "answer_index": 1, "explanation": "To'g'ri! Sanoatlashgan chorvachilik issiqxona gazlarining (ayniqsa metan) eng katta manbalaridan biridir." },
    { "id": "bp50", "story": "Odamlar ekinlarni yovvoyi to'ng'izlar yemasin deb ularni zaharlab o'ldirishdi. Ko'p o'tmay o'rmonda daraxtlar quriy boshladi.", "question": "To'ng'izning bunga qanday aloqasi bor?", "options": ["Aloqasi yo'q", "To'ng'izlar tuproqni kovlab yumshatib turgan, yong'oq va urug'larni ko'mib yangi daraxtlar o'sishiga sababchi bo'lgan", "Daraxtlar qarigan"], "answer_index": 1, "explanation": "To'g'ri! Tabiatda hayvonlarning ozuqa izlashi aslida o'rmon ekotizimi uchun tuproq yumshatuvchi va urug' tarqatuvchi vazifasini bajaradi." },
    { "id": "bp51", "story": "Boyish maqsadida yashirin jinoiy guruh karkidonlarni (nosorog) faqat shoxi uchun o'ldirib ketmoqda.", "question": "Bu qaysi turdagi jinoyatga kiradi?", "options": ["Kichik huquqbuzarlik", "Xalqaro brakonyerlik bo'lib, hayvon turining genofondiga halokatli zarba (qirilib ketishiga) olib keladi", "Oddiy ov"], "answer_index": 1, "explanation": "To'g'ri! Hayvonlarning muayyan a'zosi (shoxi, tishi) uchun ovlanishi turning butunlay yo'q qilinishiga sabab bo'ladi." },
    { "id": "bp52", "story": "Olimlar baliqlar tuxumida va baliq go'shtida dorilar (antibiotiklar, gormonlar) qoldig'ini topishdi. Bu dorilar zavoddan emas, odamlarning uyidan kelgan.", "question": "Dorilar qanday qilib suvga tushgan?", "options": ["Baliqchilar bergan", "Odamlar muddati o'tgan dorilarni hojatxonaga oqizgani uchun", "Osmondan tushgan"], "answer_index": 1, "explanation": "To'g'ri! Kanalizatsiya tizimlari kimyoviy dori vositalarini tozalashga moslashmagan. Dorilar suv havzalarini zaharlaydi." },
    { "id": "bp53", "story": "Cho'l mintaqasida qattiq shamollar qum va tuzni ko'tarib minglab kilometrga uchirib ketmoqda.", "question": "Bu bo'ronlarning kuchayishiga inson qanday hissa qo'shdi?", "options": ["Shamol parraklari o'rnatgani orqali", "Orol dengizi kabi ko'llarni quritish, cho'llardagi saksovullarni o'tin uchun qirib tashlash orqali", "Hissa qo'shmagan"], "answer_index": 1, "explanation": "To'g'ri! O'simlik qoplamisiz qolgan quruq va sho'rxok tuproq kuchli chang bo'ronlari manbaiga aylanadi." },
    { "id": "bp54", "story": "Qishloqda yerlar tekislanib faqat paxta va bug'doy ekildi. Ilgari uchraydigan ko'plab qush, baqa va hasharotlar yo'qolib qoldi.", "question": "Bu jarayon ekologiyada nima deyiladi?", "options": ["Gullab yashnash", "Monokultura (faqat bir xil ekin) tufayli bioxilma-xillikning qisqarishi", "Eroziya"], "answer_index": 1, "explanation": "To'g'ri! Monokultura (bir xil ekin turi) turli xil hayvonlar va o'simliklar yashashi uchun kerakli sharoitni buzadi." },
    { "id": "bp55", "story": "O'zbekistonning issiq iqlimiga qaramay, bino fasadlarida hamma yog'i qora va qoraytirilgan oyna bo'lgan binolar ko'p qurilmoqda. Ularning ichini sovutish uchun yuzlab konditsionerlar tinimsiz ishlamoqda.", "question": "Buning ekologik oqibati qanday?", "options": ["Havo tozalanadi", "Konditsionerlardan chiqqan issiqlik shahar ko'chalarini battar isitadi, energiya sarfi (va shunga mos ravishda issiqxona gazlari) keskin ortadi", "Faqat chiroyli ko'rinadi"], "answer_index": 1, "explanation": "To'g'ri! Issiq iqlimda oynavand qora binolar (issiqxona kabi qiziydi) energiyani isrof qiluvchi va atrofni isituvchi manbadir." },
    { "id": "bp56", "story": "Yengil avtomobil egasi pulni tejash uchun mashinasidan katalizatorni olib tashlab sotib yubordi.", "question": "U tabiatga nima zarar qildi?", "options": ["Katalizatorning foydasi yo'q", "Katalizator zaharli gazlarni (is gazi, azot oksidlari) zararsizlantiruvchi filtr edi. Endi mashina havoni bir necha barobar ko'p zaharlaydi", "Mashina tezroq yuradi"], "answer_index": 1, "explanation": "To'g'ri! Katalitik neytralizator avtomobil tutunidagi zaharni tozalaydi. Uni olib tashlash (garchi javobgarlik bo'lmasa-da) ekologik jinoyatdek gap." },
    { "id": "bp57", "story": "Sayyohlar dam olish zonasida olov yoqib gulxan atrofida o'tirishdi. Ketayotganda olov ustiga ozgina tuproq tortib ketishdi. Tunda shamol turib o'rmon yonib ketdi.", "question": "Olovni o'chirish qoidasi qanday edi?", "options": ["Olovni shunday tashlab ketish kerak", "Olovga mo'l ko'l suv quyib, hech qanday tutun va cho'g' qolmaganiga to'liq ishonch hosil qilish shart edi", "Tuproq tortish kifoya qiladi"], "answer_index": 1, "explanation": "To'g'ri! Yuzaki ko'milgan cho'g' shamolda osongina alangalanadi. 90% o'rmon yong'inlariga aynan inson ehtiyotsizligi sabab bo'ladi." },
    { "id": "bp58", "story": "Zavod chiqqan oqova suvlarini maxsus biologik hovuzga to'kdi. Bu hovuzda qamish va o'ziga xos suvo'tlar o'stirilgan edi. Keyin suv daryoga quyildi.", "question": "Bu o'simliklar nima vazifa bajardi?", "options": ["Faqat chiroyli turdi", "Fito-tozalash (Fitoremediatsiya). O'simliklar va ularning ildizidagi bakteriyalar suvdagi zaharli moddalarni o'ziga yutib suvni tozalab berdi", "Suvni bulg'atdi"], "answer_index": 1, "explanation": "To'g'ri! Qamish kabi o'simliklar zaharli chiqindilarni va og'ir metallarni parchalovchi eng zo'r biologik tozalash inshootlari hisoblanadi." },
    { "id": "bp59", "story": "Suv tanqis hududda dehqon ekinlarni an'anaviy ariqdan jo'yaklab emas, balki tomchilatib sug'orish tizimi orqali sug'ora boshladi.", "question": "Ekologik jihatdan bu usulning yutug'i nimada?", "options": ["Suv juda oz tejaladi", "Suv bug'lanishi keskin kamayadi, begona o'tlar o'smaydi, tuproq eroziyasi to'xtaydi va suv 50% gacha tejaladi", "Zararli usul"], "answer_index": 1, "explanation": "To'g'ri! Tomchilatib sug'orish qishloq xo'jaligida suvni oqilona sarflashning eng ilg'or usullaridan biridir." },
    { "id": "bp60", "story": "Tog'li hududda odamlar hamma butalarni o'tin qilishdi. Qishda kuchli qor yog'di va keyin havo isib erishni boshladi. To'satdan dahshatli qor ko'chkisi (yoki sel) qishloqni bosdi.", "question": "Butalarning kesilishi bunga qanday ta'sir qildi?", "options": ["Ta'siri yo'q", "Tog' yonbag'irlaridagi buta va daraxtlarning ildizlari tuproq va qorni ushlab turuvchi asosiy \"armatura\" edi. Ular kesilgach ko'chki osonlashdi", "Qor ko'proq yog'di"], "answer_index": 1, "explanation": "To'g'ri! Tog' o'simliklari yonbag'irlarni qulashdan saqlovchi tabiiy mustahkamlovchi qatlamdir." }
]
