    { "id": "bt41", "question": "Bioxilma-xillik konvensiyasi (CBD) qachon qabul qilingan?", "options": ["1972 yil Stokgolm", "1992 yil Rio-de-Janeyro", "1997 yil Kioto"], "answer_index": 1, "explanation": "To'g'ri! Rio-de-Janeyrodagi sammitda qabul qilingan bo'lib, sayyoraning barcha jonzotlarini asrashga xizmat qiladi." },
    { "id": "bt42", "question": "Fitoremediatsiya nima?", "options": ["O'simliklar yordamida tuproq, suv yoki havoni zaharli kimyoviy moddalardan tozalash jarayoni", "Zararkunandalarga qarshi kimyoviy dori sepish", "Suvni filtrlash"], "answer_index": 0, "explanation": "To'g'ri! Fito (o'simlik), remediatsiya (tiklash, tozalash). Ba'zi o'simliklar og'ir metallarni va zaharlarni uziga shimib, yerni tozalaydi." },
    { "id": "bt43", "question": "Karbonat angidrid (Uglerod) yutqichlari nimalar?", "options": ["Zavod trubalari", "O'rmonlar va okeanlar (u yerdagi fitoplanktonlar)", "Cho'llar"], "answer_index": 1, "explanation": "To'g'ri! Ular CO2 gazini katta miqdorda o'zida saqlab qoladigan eng yirik tabiiy zaxiralardir." },
    { "id": "bt44", "question": "Dioksinlar nima?", "options": ["Foydali vitaminlar", "Plastik, rezina va maishiy chiqindilarni past haroratda ochiq yoqishdan hosil bo'luvchi eng o'ta zaharli va kanserogen (rak qiliuvchi) modda", "Atir guli ifori"], "answer_index": 1, "explanation": "To'g'ri! Dioksin tabiatda parchalanmaydi, inson immunitetini va genini yo'q qiluvchi kuchli zahardir." },
    { "id": "bt45", "question": "Ekoturizm (Ekologik turizm) nima?", "options": ["Shaharlarda dam olish", "Yovvoyi tabiatning buzilmagan joylariga tabiatga ziyon yetkazmasdan, mahalliy aholi va tabiatni asrashga hissa qo'shib sayohat qilish", "Mehmonxona qurish"], "answer_index": 1, "explanation": "To'g'ri! Ekoturizmning asosiy qoidasi: \"Tabiatda faqat izingni qoldir, undan faqat suratlar olib ket\"." },
    { "id": "bt46", "question": "Brakish suv nima?", "options": ["Toza ichimlik suvi", "Dengiz sho'r suvi", "Chuchuk suv bilan dengiz suvi aralashgan, biroz sho'rtob suv (masalan, daryolar dengizga quyiladigan joylarda)", "Zaharli suv"], "answer_index": 2, "explanation": "To'g'ri! Bu hududlarda o'ziga xos ekotizim va faqat shu yerga moslashgan hayvonlar yashaydi." },
    { "id": "bt47", "question": "Zararkunandalarga qarshi Integratsiyalashgan kurash (IPM) nima?", "options": ["Faqat eng kuchli zaharlarni ishlatish", "Biologik, mexanik va faqat o'ta zarur bo'lganda ozgina kimyoviy usullarni birgalikda qo'llab, hosilni saqlab qolish", "Hech narsa qilmaslik"], "answer_index": 1, "explanation": "To'g'ri! Zamonaviy agronomiyada zaharlardan faqat eng so'nggi chora sifatida va qat'iy me'yorda foydalaniladi." },
    { "id": "bt48", "question": "Permafrost (Mangu muzliklar) nima?", "options": ["Muzlatgichlar", "Yer yuzining shimoliy hududlarida minglab yillar davomida erimagan, doimiy muzlab yotuvchi tuproq (va muz) qatlami", "Qishki qor"], "answer_index": 1, "explanation": "To'g'ri! Global isish sababli mangu muzliklar erimoqda va u yerdan ulkan miqdordagi metan gazi havoga chiqib ketmoqda." },
    { "id": "bt49", "question": "Pelagik zona nima?", "options": ["Tog'ning uchi", "Okean yoki ko'lning qirg'oqdan yoki tubidan uzoqroq bo'lgan erkin va ochiq suv ustuni qismi", "Daryo quyi oqimi"], "answer_index": 1, "explanation": "To'g'ri! Bu yerda nekton va planktonlar (baliqlar, meduzalar) faol yashaydi." },
    { "id": "bt50", "question": "Bentik zona nima?", "options": ["Suv usti", "Okean yoki ko'lning eng tubidagi tuproqli va g'ovak qismi bo'lib, u yerda bentos (tub) organizmlari yashaydi", "Atmosfera buluti"], "answer_index": 1, "explanation": "To'g'ri! Qisqichbaqasimonlar, dengiz yulduzlari asosan bentik zonada yashaydi." },
    { "id": "bt51", "question": "Gidrologik qurg'oqchilik nima?", "options": ["Bir kun yomg'ir yog'masligi", "Ko'llar, daryolar va yer osti suv sathining keskin va uzoq muddatga pasayib ketishi", "Qum bo'roni"], "answer_index": 1, "explanation": "To'g'ri! Bu qurg'oqchilik ekotizim va iqtisodiyot uchun eng xavfli tur hisoblanadi." },
    { "id": "bt52", "question": "Xalqaro qoidalarga ko'ra Qizil kitobning vazifasi nima?", "options": ["Hayvonlarni otishga ruxsat berish", "Noyob va yo'qolib borayotgan turlarning saqlanib qolishi va ko'payishi uchun zarur choralarni ishlab chiqish hamda jamoatchilikni ogoh etish", "Faqat ro'yxatga olish"], "answer_index": 1, "explanation": "To'g'ri! Qizil kitob ogohlantiruvchi signal xususiyatiga ega hujjatdir." },
    { "id": "bt53", "question": "Klimatologiyada Albedo nima?", "options": ["Shamol tezligi", "Yer yuzasining quyosh nurlarini qaytarish qobiliyati (masalan, qor va muz yorug'likni 90% qaytaradi)", "Tog' cho'qqisi"], "answer_index": 1, "explanation": "To'g'ri! Muzliklarning erishi Yerning albedosini (qaytarish qobiliyatini) pasaytiradi va yer ko'proq issiqlikni yuta boshlaydi." },
    { "id": "bt54", "question": "Ekologik izchillik (Barqaror rivojlanish / Sustainable development) nima?", "options": ["Barcha resurslarni bir kunda sarflash", "Kelajak avlodlarning o'z ehtiyojlarini qondirish qobiliyatiga putur yetkazmagan holda, hozirgi zamon ehtiyojlarini qondirish", "Faqat sanoat qurish"], "answer_index": 1, "explanation": "To'g'ri! Bu insoniyatning yashab qolish va tabiat bilan hamohang rivojlanish falsafasidir." },
    { "id": "bt55", "question": "Kompostlash nima?", "options": ["Plastikni eritish", "O'simlik qoldiqlari, oziq-ovqat chiqindilari va go'ngni chirishiga (fermentatsiya) sharoit yaratib, tabiiy o'g'it (kompost) olish jarayoni", "Chiqindini yoqish"], "answer_index": 1, "explanation": "To'g'ri! Kompostlash organik chiqindilardan qutilishning ekologik toza va eng foydali usulidir." },
    { "id": "bt56", "question": "Iqlim muhojirlari (Climate refugees) kimlar?", "options": ["Dam olishga borayotganlar", "Iqlim o'zgarishi, qurg'oqchilik, suv toshqini kabi ekologik halokatlar sababli o'z yashash joyini tark etishga majbur bo'lgan odamlar", "Sayyohlar"], "answer_index": 1, "explanation": "To'g'ri! Orolbo'yi mintaqasida yashagan minglab insonlar shunga misol bo'la oladi." },
    { "id": "bt57", "question": "Freonlar atmosferada qanday ziyon keltiradi?", "options": ["Issiqlik tarqatadi", "Ulardagi xlor va brom atomlari ozon molekulalarini parchalab tashlaydi", "Bulutlarni yo'q qiladi"], "answer_index": 1, "explanation": "To'g'ri! Bitta xlor atomi 100 mingta ozon molekulasini yemirishga qodir." },
    { "id": "bt58", "question": "Urban ekologiyasi (Shahar ekologiyasi) nimani o'rganadi?", "options": ["Qishloq hayotini", "Shahar ekotizimidagi insonlar, tabiat va sun'iy muhit o'rtasidagi o'zaro murakkab munosabatlarni", "Faqat transport harakatini"], "answer_index": 1, "explanation": "To'g'ri! U shaharlarda qanday qilib daraxtlar, havo va odamlar uyg'unlikda yashashini o'rganadi." },
    { "id": "bt59", "question": "Antropotsentrizm nima?", "options": ["Tabiat hukmronligi", "Odamni tabiatning hukmdori va markazi deb biladigan, tabiat faqat inson ehtiyojlari uchun yaratilgan degan (noto'g'ri) qarash", "Barcha organizmlar tengligi"], "answer_index": 1, "explanation": "To'g'ri! Bunday xudbinona yondashuv zamonaviy ekologik halokatlarning asosiy falsafiy sababchisi bo'ldi." },
    { "id": "bt60", "question": "Ekosentrizm nima?", "options": ["Markaziy Osiyo ekologiyasi", "Butun tabiat, uning barcha tirik va jonsiz elementlari ichki qadr-qimmatga ega bo'lib, inson faqat uning bir bo'lagi ekanligini anglatuvchi dunyoqarash", "Faqat iqtisodiyot"], "answer_index": 1, "explanation": "To'g'ri! Ekosentrizm insonga tabiatga ehtiyotkor va hurmat bilan munosabatda bo'lishni o'rgatadi." }
]
"@

$newPenaltiesStr = @"
[
    { "id": "bpn41", "question": "Yerlardan noqonuniy qum yoki shag'al qazib olish qanday oqibatga olib keladi? (MJtK 70-1-modda)", "options": ["Foyda keltiradi", "Foydali qazilmalarni ruxsatsiz qazib olish ashyolarni musodara qilib, jarima solishga (yoki jinoiy ishga) sabab bo'ladi", "Faqat ogohlantirish"], "answer_index": 1, "explanation": "To'g'ri! Daryo va tog'lardan noqonuniy qum va tosh qazish daryo o'zanini buzadi va atrof muhitga katta ziyon keltiradi." },
    { "id": "bpn42", "question": "Qurilish materiallari (masalan sement) ishlab chiqaruvchi zavod havoni ifloslantirsa, uning javobgarligi o'zgaradimi?", "options": ["Yo'q, zavod yopilmaydi", "Qonunbuzarlik davom etsa uning faoliyati Ekologiya vazirligi va sud qarori bilan butunlay to'xtatib qo'yilishi mumkin", "Jarima to'lab yuraveradi"], "answer_index": 1, "explanation": "To'g'ri! Aholi sog'lig'iga va ekologiyaga xavf tug'dirgan har qanday zavod ishlashdan to'xtatib qo'yiladi." },
    { "id": "bpn43", "question": "Avtomobil oynasidan ko'chaga (yoki daryoga) pista po'chog'i yoxud baklajka uloqtirgan haydovchiga jarima bormi?", "options": ["Yo'q, u kichkina axlat", "Ha, \"Avtomobildan chiqindi tashlash\" ma'muriy huquqbuzarlik sanalib, jarima undiriladi", "Faqat piyodalarga mumkin"], "answer_index": 1, "explanation": "To'g'ri! Transportdan chiqindi tashlash ekologiya va yo'l qoidalariga ko'ra jazoga tortiladi." },
    { "id": "bpn44", "question": "Hayvonlarning bolalarini (masalan, kiyikchani yoki ayiqchani) yovvoyi tabiatdan o'g'irlab uyda boqish qonuniymi?", "options": ["Ha, agar yaxshi boqsa", "Mutlaqo noqonuniy, yovvoyi hayvonlarni davlat ruxsatisiz tutqunlikda saqlash (brakonyerlik) jarima va jinoiy javobgarlikka sabab bo'ladi", "Faqat yozda mumkin"], "answer_index": 1, "explanation": "To'g'ri! Yovvoyi jonzotlar davlat mulki va tabiatning ajralmas qismidir." },
    { "id": "bpn45", "question": "Baliq ovlash davrida (uvildiriq sochish vaqtida) suv omborlarida motorli qayiqlarda baland ovoz chiqarib suzish mumkinmi?", "options": ["Mumkin", "Ta'qiqlanadi! Shovqin baliqlarning ko'payishiga xalaqit beradi va bu harakat javobgarlikka tortiladi", "Faqat bayram kunlari"], "answer_index": 1, "explanation": "To'g'ri! Bahor mavsumida barcha suv havzalarida qat'iy sokinlik rejimi o'rnatiladi." },
    { "id": "bpn46", "question": "Zararli kimyoviy moddalarni (pestisid va o'g'itlarni) ochiq havoda, yomg'ir tagida saqlagan ombor mudiri nima uchun javobgar?", "options": ["Zarari yo'q", "Saqlash qoidalarini buzib, zaharning atrof muhitga oqib ketishiga sabab bo'lgani uchun javobgar bo'ladi", "Foydali modda-ku"], "answer_index": 1, "explanation": "To'g'ri! Kimyoviy moddalarni saqlash xavfsizligi bo'yicha maxsus qat'iy talablar mavjud." },
    { "id": "bpn47", "question": "Bir guruh odamlar milliy bog'ga dam olgani borib, daraxtlarga o'z ismlarini o'yib yozishdi. Bu uchun jazo bormi?", "options": ["Yo'q, bu san'at", "Ha, daraxtga qasddan shikast yetkazish deb baholanadi va jarima solinadi", "Faqat bolalarga mumkin"], "answer_index": 1, "explanation": "To'g'ri! Daraxt po'stlog'ini ko'chirish uni kasallantiradi, bu daraxtni shikastlash hisoblanadi." },
    { "id": "bpn48", "question": "Shaharsozlik va qurilish loyihalarida yashil hududlar (daraxtzorlar) maydoni saqlanmasdan, hammasi betonlab tashlansa kim javobgar?", "options": ["Hech kim", "Loyiha bo'yicha ekologik ekspertiza talabini buzgan arxitektor va mas'ul shaxslar ma'muriy javobgarlikka tortiladi", "Quruvchilar"], "answer_index": 1, "explanation": "To'g'ri! Qurilish me'yorlariga ko'ra har qanday ob'ekt atrofida ma'lum miqdorda ko'kalamzor hudud bo'lishi shart." },
    { "id": "bpn49", "question": "Radioaktiv chiqindilarni boshqa hududga qanday tartibda olib o'tish mumkin?", "options": ["Oddiy yuk mashinasida", "Faqat maxsus davlat nazorati ostida, yashirin holda tashish esa o'ta og'ir jinoiy javobgarlikka tortiladi", "Xohlagan vaqtda"], "answer_index": 1, "explanation": "To'g'ri! Xavfli qoldiqlarni harakati (transportirovkasi) hukumat ruxsati bilan qat'iy nazorat qilinadi." },
    { "id": "bpn50", "question": "Dehqon tuproqqa shunchalik ko'p zaharli dori sepib yubordiki, tuproqdagi qurt-qumursqa va chuvalchanglar qirilib, yer toshdek qotib qoldi. Bunga qonun bormi?", "options": ["Yer o'ziniki, xohlaganini qiladi", "Tuproqni kimyoviy moddalar bilan zaharlaganlik (yerning buzilishi) uchun jiddiy jarimaga tortiladi va uning yerga egalik huquqi bekor qilinishi mumkin", "Jazo yo'q"], "answer_index": 1, "explanation": "To'g'ri! Yer davlat himoyasidagi umummilliy boylik, yer egasi faqat undan oqilona foydalanishi shart." },
    { "id": "bpn51", "question": "Oqova suvlarni (kanalizatsiyani) tozalamasdan to'g'ridan-to'g'ri anhorga oqizayotgan kafe (choyxona) egasiga qanday chora ko'riladi?", "options": ["Faqat hayfsan", "Unga jarima solinadi, zarari hisoblanadi va quvurni darhol uzib qo'yish chorasi ko'riladi", "Arzon jarima"], "answer_index": 1, "explanation": "To'g'ri! Suv havzalariga tozalanmagan maishiy chiqindilarni tushirish kasalliklar tarqatish xavfi tufayli juda qattiq taqiqlanadi." },
    { "id": "bpn52", "question": "Zavod rahbari ekologik monitoring (tekshirish) apparatlarini o'chirib qo'ydi, toki havoga qancha zahar chiqayotgani bilinmasin. Ushbu xatti-harakat qanday jazolanadi?", "options": ["Bu uning ishi", "Tabiatni muhofaza qilish inshootlarini (filtr va nazorat uskunalarini) ataylab ishlatmaslik deb baholanib, javobgarlik (jarima) keskin ortadi", "Jarima bo'lmaydi"], "answer_index": 1, "explanation": "To'g'ri! Ekologik nazorat asboblarini yashirish yoki o'chirish qasddan qilingan huquqbuzarlik sanaladi." },
    { "id": "bpn53", "question": "Noyob gullar va dorivor o'simliklarni tonnalab (katta hajmda) ruxsatsiz terib olib, chetga sotgan tadbirkor jazolanadimi?", "options": ["Yo'q, ular dorivor", "Ha, o'simlik dunyosidan noqonuniy foydalanganlik va Qizil kitob turlarini yo'q qilganlik uchun juda ulkan miqdorda moddiy zarar undiriladi (yoki jinoyat ishi)", "Faqat mol-mulki olinadi"], "answer_index": 1, "explanation": "To'g'ri! Dorivor va yovvoyi o'simliklarni tijorat maqsadida yig'ish faqat kvota (ruxsatnoma) bilan pullik asosda bo'ladi." },
    { "id": "bpn54", "question": "Issiqxona (parnik) isitish uchun eski shinalar va kauchuklarni yoqish javobgarlik keltirib chiqaradimi?", "options": ["Ha, atmosfera havosini zaharli tutun bilan o'ta kuchli ifloslantirgani uchun tegishli javobgarlikka tortiladi", "Yo'q, qishda o'zini isitishi kerak", "Jazo yo'q"], "answer_index": 0, "explanation": "To'g'ri! Shina (rezina) yoqish atrofdagilar orasida rak kasalligini keltirib chiqaruvchi eng zaharli tutun chiqaradi." },
    { "id": "bpn55", "question": "Ovchilik guvohnomasisiz o'z iti yordamida dalada quyon ovlash brakonyerlikka kiradimi?", "options": ["Yo'q", "Ha, ov qilish usulidan (qurol, it, qopqon) qat'iy nazar ruxsatsiz tutilgan har qanday yovvoyi hayvon uchun javobgarlik belgilanadi", "Faqat miltiqda otsa brakonyer"], "answer_index": 1, "explanation": "To'g'ri! Yovvoyi jonivorlarni hatto tayoq bilan ushlasa ham, qonunsiz harakat sanaladi." },
    { "id": "bpn56", "question": "Quyosh va shamol elektr stansiyasi (QES) barpo etayotgan investor ham Ekologik ekspertizadan o'tishi kerakmi?", "options": ["Yo'q, u yashil energiya", "Ha, har qanday yirik inshoot qurilishi atrof muhitga (masalan, qushlarning uchishiga) ta'sirini baholash uchun Davlat ekologik ekspertizasidan o'tishi shart", "Ixtiyoriy"], "answer_index": 1, "explanation": "To'g'ri! Hatto ekologik toza stansiyalar qurilishi ham mahalliy bioxilma-xillikka (tuproq, qushlar) salbiy ta'sir ko'rsatmasligi kerak." },
    { "id": "bpn57", "question": "Ekologik jarimalardan tushgan mablag'lar qayerga yo'naltiriladi?", "options": ["Faqat byudjetga", "Asosan Ekologiya, atrof-muhitni muhofaza qilish va iqlim o'zgarishi jamg'armasiga, tabiatni tiklash dasturlari uchun", "Tashkilot xodimlariga"], "answer_index": 1, "explanation": "To'g'ri! Undirilgan zarar pullari yana qaytadan daraxt ekish, hayvonlarni asrash va tabiatni tiklashga ishlatiladi." },
    { "id": "bpn58", "question": "Tunda daryodan ekskavator bilan qum qaziyotganlar huquqni muhofaza qilish xodimlari tomonidan ushlandi. Uskunaga (ekskavatorga) nima bo'ladi?", "options": ["Egasiga qaytariladi", "Brakonyerlik vositasi sifatida huquqbuzarlik ob'ekti tariqasida qonuniy sud orqali davlat foydasiga musodara qilinadi", "Faqat jarima"], "answer_index": 1, "explanation": "To'g'ri! Noqonuniy harakatda ishlatilgan har qanday texnika davlat foydasiga musodara qilinishi mumkin." },
    { "id": "bpn59", "question": "Ekologiya vazirligining Davlat inspektorlari xizmat vazifasini bajarayotgan vaqtida o'qotar qurol ko'tarishga va uni qo'llashga haqlimi?", "options": ["Yo'q", "Ha, agar brakonyerlar tomonidan hayotiga xavf tug'ilsa (o'zini himoya qilish uchun) ularda xizmat qurolini ko'tarib yurish va qonuniy qo'llash huquqi bor", "Faqat rezina o'qlar"], "answer_index": 1, "explanation": "To'g'ri! Inspektorlarning hayoti tabiatni asrash vaqtida qurollangan brakonyerlar tomonidan ko'p xavf ostida qoladi." },
    { "id": "bpn60", "question": "Kimyoviy moddalar yoki pestitsidlardan foydalanish, tashish va saqlash qoidalarini buzganlik (MJtK 87-modda) fuqarolarga qanday jarima soladi?", "options": ["BHM 1 baravari", "BHMning 1 dan 3 baravarigacha, mansabdor shaxslarga esa 3 dan 5 baravarigacha", "Faqat hayfsan"], "answer_index": 1, "explanation": "To'g'ri! Pestisid va kimyoviy o'g'itlarni noto'g'ri saqlash juda xavfli bo'lib, zudlik bilan jarima solinadi." }
]
