$newTrueFalseStr = @"
[
    { "id": "btf41", "question": "Gidrosferaning deyarli barcha suvlari insoniyat ichishi uchun yaroqlidir.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Dunyo okeani 97% suvni tashkil qiladi va u sho'rdir. Faqat 3% chuchuk suv (uning ham ko'pi muzlikda) mavjud." },
    { "id": "btf42", "question": "Agar birorta hasharot tabiatdan butunlay qirilib ketsa, bu ekotizimga hech qanday zarar qilmaydi.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Tabiat - zanjirdek gap. Biror hasharot yo'qolsa, uni yeydigan qushlar och qoladi, qushlar yo'qolsa boshqa zararkunandalar ko'payadi." },
    { "id": "btf43", "question": "Yerdagi iqlim isishini (global isishni) bugun darhol to'xtatib qo'yish mumkin.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Hozirgacha to'plangan CO2 atmosferada yuzlab yillar saqlanib qoladi. Jarayon inersiya bilan baribir bir necha o'n yillar davom etadi." },
    { "id": "btf44", "question": "Shamoldan va quyoshdan energiya olish jarayonida umuman hech qanday kimyoviy qoldiq chiqmaydi.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Bu aynan shuning uchun eng 'yashil' va toza energiya manbai sanaladi." },
    { "id": "btf45", "question": "Daraxt barglari ustiga yig'ilgan changlar tuproqqa yomg'ir orqali tushganda, ular o'simliklar uchun o'g'it vazifasini ham bajarishi mumkin.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Shahar va tabiiy changlar tarkibida ko'plab mikroelementlar mavjud, daraxt yomg'ir yuvganidan so'ng yana havoni tozalaydi." },
    { "id": "btf46", "question": "Plastik idishlarni tashlamasdan ularni hovlida yoqib yuborish - axlatni kamaytirishning eng oson va ekologik toza yo'lidir.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Plastikni yoqish uning chirishidan ko'ra yuz marta xavfliroq, bu saratonga sabab bo'luvchi zaharni osmonga purkash bilan tengdir." },
    { "id": "btf47", "question": "Suv sathi tushib, qurib borayotgan barcha ko'llar Orol dengizi kabi halokatga uchrashi aniq.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Ba'zi ko'llarning qurishi va botqoqqa aylanishi (suksessiya) tabiiy va geologik me'yoriy jarayondir, faqat insonsiz bu jarayon minglab yillar davom etadi." },
    { "id": "btf48", "question": "Hayvonot bog'lari (Zooparklar) kamyob turlarni asrab qolish va ularni ko'paytirib tabiatga qaytarishda muhim rol o'ynaydi.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Zamonaviy zooparklarning asosiy maqsadi shunchaki tomosha ko'rsatish emas, noyob turlarning genofondini saqlab qolishdir." },
    { "id": "btf49", "question": "Avtomobilning dvigatel hajmi qanchalik kichik bo'lsa (masalan kichik litrajli mashinalar) odatda atmosferaga chiqindi gazlari shunchalik kam chiqadi.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Kichik hajmli motorlar kam yoqilg'i sarflaydi, demak tabiatga ham shunga yarasha kam ziyon yetkazadi." },
    { "id": "btf50", "question": "Suv tubidagi organizmlar (bentos) suvdagi chiqindilar bilan oziqlanib, suvning o'zini o'zi tozalashida qatnashmaydi.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Bental organizmlar (masalan suv shillig'i va chig'anoqlar) daryoning tirik filtrlaridir. Ular barcha organik chiqindilarni yeb tozalab beradi." },
    { "id": "btf51", "question": "Ko'mir yoqilg'isidan foydalanuvchi elektr stansiyalari atom (yadro) elektr stansiyalariga qaraganda havoni ko'proq ifloslantiradi va radioaktiv elementlar ajratadi.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Garchi ajablanarli bo'lsa-da, ko'mir tutunida uran va toriy kabi radioaktiv qoldiqlar bo'ladi va ular havoga me'yoriy ishlaydigan AESdan ko'proq zahar sochadi." },
    { "id": "btf52", "question": "Insonlarning suvga munosabati oqibatida ko'pgina yirik daryolar okeanga yetib bormasdan qurib qolmoqda.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Amudaryo va Kolorado kabi ulkan daryolar ko'pincha daryo etagida mutlaqo qurib qolib okeanga (dengizga) yetib bormaydi." },
    { "id": "btf53", "question": "Hozirgi vaqtda yovvoyi tabiatning halokatiga asosiy sababchi yirtqich hayvonlarning ko'payib ketishi hisoblanadi.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Hayvonlar olamiga eng xavfli tahdid – bu insonlarning ularning yashash muhitini (o'rmon va cho'llarni) yo'q qilayotgani va iqlim o'zgarishidir." },
    { "id": "btf54", "question": "Elektron chiqindilar (eski telefon, kompyuter, televizor) oddiy axlat qutisiga tashlanishi kerak emas.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Elektronika tarkibida ko'p miqdorda zaharli qo'rg'oshin, simob, va kadmiy bor, ular faqat maxsus korxonalarda utilizatsiya qilinishi shart." },
    { "id": "btf55", "question": "Dunyodagi barcha cho'llar faqat havo juda issiq bo'lgan joylarda joylashgan.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Cho'l tushunchasi issiqlikka emas, balki yog'ingarchilik kamligiga bog'liq. Masalan, Antarktida ham quruq muzli cho'l hisoblanadi." },
    { "id": "btf56", "question": "Agar dunyo darajasida go'sht iste'moli kamaytirilsa, bu iqlim o'zgarishini sekinlashtirishga yordam beradi.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Sanoat mollari millionlab gektar o'rmonni emirilishiga va metan gazi chiqarilishiga olib kelgani uchun, go'shtning kam iste'mol qilinishi katta foydadir." },
    { "id": "btf57", "question": "O'zbekistonda yovvoyi holda o'sadigan va yo'qolib ketayotgan za'faron (krokus), lola va boychechak kabi gullarni har qancha terish mumkin.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Bu gullar qattiq muhofazada va ularni terish ma'muriy (yoki jinoiy) javobgarlikka olib keladi." },
    { "id": "btf58", "question": "Mikroplastik zarralari shunchalik maydaki, ular hozirda barcha insonlarning (va hatto chaqaloqlarning) qonidan va organlaridan topilmoqda.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Mikroplastiklar ozuqa va havo orqali butun oziq zanjirining, jumladan insonlarning ham tanasiga o'rnashib olgan." },
    { "id": "btf59", "question": "Xalqaro qoidalarga asosan atrof-muhit musaffoligiga erishish uchun iqtisodiy o'sish va zavodlar qurilishini butunlay to'xtatish yagona yo'l hisoblanadi.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Insoniyat izchil (barqaror) rivojlanish konvensiyasiga amal qiladi: bu yerda ham iqtisodiyot rivojlanadi, ham ekologik toza texnologiyalar qo'llaniladi." },
    { "id": "btf60", "question": "Daraxt va o'rmonlar nafaqat yomg'irni keltirib chiqaradi, balki bulutlarni o'ziga tortuvchi 'bio-nasos' vazifasini ham bajaradi.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Qalin o'rmonlar atmosfera havosini namlik bilan to'yintiradi va daryolarning shakllanishida kuchli ahamiyatga ega." }
]
"@

$newQ = ConvertFrom-Json -InputObject $newQuizzesStr
$newP = ConvertFrom-Json -InputObject $newPuzzlesStr
$newT = ConvertFrom-Json -InputObject $newTermsStr
$newPn = ConvertFrom-Json -InputObject $newPenaltiesStr
$newTf = ConvertFrom-Json -InputObject $newTrueFalseStr

$jsonObj.quizzes += $newQ
$jsonObj.puzzles += $newP
$jsonObj.terms += $newT
$jsonObj.penalties += $newPn
$jsonObj.truefalse += $newTf

$jsonObj | ConvertTo-Json -Depth 10 | Set-Content -Path $jsonFile -Encoding UTF8
